INSERT INTO `blog_authors` (`id_author`, `name`, `role`, `department`, `avatar`, `bio`) VALUES ('dr_lan_anh', 'BS. CKII Nguyễn Lan Anh', 'Bác sĩ Chuyên khoa II Da liễu - Cố vấn Y khoa Hoàng Bảo', 'Hội đồng Da liễu Lâm sàng & Thẩm mỹ TP.HCM', 'https://images.unsplash.com/photo-1594824813629-87cfa77d0186?w=400&q=80&auto=format&fit=crop', 'Bác sĩ Lan Anh có hơn 14 năm kinh nghiệm công tác tại các bệnh viện da liễu tuyến đầu, chuyên nghiên cứu về sinh lý học màng lipid biểu bì và phục hồi da tổn thương sau can thiệp thẩm mỹ.') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);
INSERT INTO `blog_authors` (`id_author`, `name`, `role`, `department`, `avatar`, `bio`) VALUES ('mai_phuong', 'Nhà báo Mai Phương', 'Trưởng ban Biên tập Khoa học Làn da & Mỹ phẩm', 'Tạp chí Hoàng Bảo Beauty Journal', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400&q=80&auto=format&fit=crop', 'Tốt nghiệp cử nhân Hóa dược Đại học Quốc gia, Mai Phương đã có 9 năm theo đuổi mảng báo chí phân tích hoạt chất mỹ phẩm và phỏng vấn các chuyên gia đầu ngành trong và ngoài nước.') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);
INSERT INTO `blog_authors` (`id_author`, `name`, `role`, `department`, `avatar`, `bio`) VALUES ('hoang_nam', 'Chuyên gia Hoàng Nam', 'Giám đốc Nghệ thuật & Chuyên gia Trang điểm Cao cấp', 'Ban Đào tạo Nghệ thuật Trang điểm Chuyên nghiệp', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=400&q=80&auto=format&fit=crop', 'Từng tu nghiệp tại Paris và Seoul, Hoàng Nam sở hữu hơn 10 năm kinh nghiệm định hình phong cách trang điểm cho các tuần lễ thời trang và cố vấn sắc tố da cho người phụ nữ Á Đông.') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`);
INSERT INTO `articles` (`id_article`, `title`, `subtitle`, `id_category`, `id_author`, `published_date`, `time_published`, `read_time`, `views`, `thumbnail`, `photo_credit`, `summary`, `pull_quote`, `tags`, `content_intro`, `content_conclusion`, `recommended_products`) VALUES ('skincare-routine-beginner', 'Giải mã quy trình 7 bước dưỡng da chuẩn da liễu: Cơ chế thẩm thấu và nguyên lý phục hồi màng lipid', 'Nhiều người chi hàng chục triệu đồng cho serum cao cấp nhưng làn da vẫn sần sùi bít tắc. Bản báo cáo chuyên sâu này sẽ phân tích tường tận nguyên lý hấp thu tế bào và thứ tự chăm sóc khoa học.', 'skincare', 'dr_lan_anh', '15/09/2026', '08:30', '8 phút đọc', 4820, 'https://images.unsplash.com/photo-1576426863848-c21f53c60b19?w=1400&q=85&auto=format&fit=crop', 'Getty Images / Tư liệu nghiên cứu Viện Da liễu Quốc tế', 'Phân tích cơ chế sinh học đằng sau kỹ thuật Double Cleansing, nguyên lý ngậm nước đa tầng của Hyaluronic Acid và vai trò tối thượng của việc củng cố lớp màng Ceramide bảo vệ da.', '{"quote": "Làn da không phải là một chiếc xô để chúng ta đổ dồn dập mọi hoạt chất đắt tiền vào. Nó là một cơ quan sống với hệ sinh thái vi sinh vật và cấu trúc biểu mô đa tầng đòi hỏi sự tôn trọng nhịp sinh học tự nhiên.", "speaker": "BS. CKII Nguyễn Lan Anh (Cố vấn Y khoa Hoàng Bảo)"}', '["Sinh lý da", "Skincare Routine", "Làm sạch kép", "Hàng rào lipid", "Da liễu học"]', 'Theo thống kê lâm sàng tại các phòng khám da liễu lớn năm 2025, có tới hơn 68% trường hợp bệnh nhân gặp tình trạng viêm da tiếp xúc hoặc bùng phát mụn ẩn không phải do thiếu mỹ phẩm, mà do sử dụng quá nhiều sản phẩm sai thứ tự và triệt tiêu màng ẩm sinh học của cơ thể. Để các phân tử dưỡng chất có thể xuyên qua lớp sừng dày từ 15-20 lớp tế bào dẹt, quy trình chăm sóc cần được thiết kế dựa trên định luật khuếch tán Fick và độ phân cực của từng nhóm dung môi.', 'Chăm sóc da khoa học là sự hòa hợp giữa kiến thức sinh lý và tính kỷ luật đều đặn mỗi ngày. Khi bạn từ bỏ thói quen bôi thoa theo trào lưu thiếu căn cứ và bắt đầu lắng nghe phản ứng sinh học của làn da, bạn sẽ nhận thấy sự biến chuyển ngoạn mục: lỗ chân lông se khít tự nhiên, độ đàn hồi gia tăng và làn da toát lên vẻ căng bóng khỏe mạnh từ sâu bên trong.', '[{"name": "Nước Hoa Hồng Cân Bằng Cấp Ẩm Chuyên Sâu Hoàng Bảo", "category": "Toner Dược Liệu", "price": 350000}, {"name": "Tinh Chất Phục Hồi Dịu Da B5 & Rau Má Tinh Khiết", "category": "Serum Chuyên Sâu", "price": 450000}, {"name": "Kem Dưỡng Sinh Học Phục Hồi Màng Lipid Ceramide Complex", "category": "Kem Dưỡng Khóa Ẩm", "price": 390000}]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `articles` (`id_article`, `title`, `subtitle`, `id_category`, `id_author`, `published_date`, `time_published`, `read_time`, `views`, `thumbnail`, `photo_credit`, `summary`, `pull_quote`, `tags`, `content_intro`, `content_conclusion`, `recommended_products`) VALUES ('sunscreen-common-mistakes', 'Nghiên cứu lâm sàng về 5 sai lầm khi thoa kem chống nắng: Vì sao chỉ số SPF trên nhãn chai không phát huy tác dụng?', 'Tại sao bạn bôi kem chống nắng đều đặn mỗi sáng nhưng vết nám và đốm nâu vẫn xuất hiện sau tuổi 25? Chuyên gia quang sinh học bóc tách các sai số phổ biến trong thói quen bảo vệ da.', 'skincare', 'mai_phuong', '12/09/2026', '14:15', '7 phút đọc', 4190, 'https://images.unsplash.com/photo-1532453288672-3a27e9be9efd?w=1400&q=85&auto=format&fit=crop', 'Phòng Thí nghiệm Quang sinh học & Thử nghiệm SPF Lâm sàng', 'Phân tích định lượng liều dùng 2mg/cm², hiện tượng phân rã màng lọc quang phổ rộng dưới nhiệt lượng và giải pháp dặm lại kem chống nắng cho người trang điểm.', '{"quote": "Kem chống nắng không phải là áo giáp bất khả xâm phạm. Nếu bôi sai liều lượng hoặc quên dặm lại, bạn đang tạo ra một ảo tưởng an toàn nguy hiểm cho các tế bào biểu bì bên dưới.", "speaker": "Nhà báo Mai Phương (Trưởng ban Khoa học Làn da)"}', '["Kem chống nắng", "Tia UVA/UVB", "Quang hóa học", "Sạm nám da", "Bảo vệ da"]', 'Bức xạ tử ngoại mặt trời gồm tia UVB (bước sóng 290-320nm gây bỏng rát, đỏ da) và tia UVA (bước sóng 320-400nm len lỏi sâu vào hạ bì, phá vỡ cấu trúc collagen và làm đứt gãy sợi elastin). Hơn 95% lượng tia UV chạm tới mặt đất là tia UVA, loại bức xạ có khả năng xuyên qua mây mù, sương sớm và cả kính cửa sổ văn phòng. Dù bạn ở trong phòng máy lạnh cả ngày, làn da vẫn đang âm thầm bị tổn thương DNA nếu không được bảo vệ đúng cách.', 'Kem chống nắng không chỉ là một sản phẩm làm đẹp đơn thuần, mà là phương pháp y tế dự phòng hiệu quả và kinh tế nhất chống lại sự suy thoái ADN tế bào và ung thư biểu mô da. Hãy xây dựng thói quen thoa đủ liều lượng và dặm lại như một nguyên tắc bất biến để bảo vệ làn da thanh xuân qua năm tháng.', '[{"name": "Kem Chống Nắng Vật Lý Lai Hóa Học SPF50+ PA++++ Kiềm Dầu", "category": "Chống Nắng Y Khoa", "price": 420000}, {"name": "Xịt Khoáng Chống Nắng Bảo Vệ Phổ Rộng Dặm Nhanh", "category": "Chống Nắng Tiện Lợi", "price": 295000}]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `articles` (`id_article`, `title`, `subtitle`, `id_category`, `id_author`, `published_date`, `time_published`, `read_time`, `views`, `thumbnail`, `photo_credit`, `summary`, `pull_quote`, `tags`, `content_intro`, `content_conclusion`, `recommended_products`) VALUES ('bha-aha-niacinamide-guide', 'Bách khoa toàn thư hoạt chất: So sánh cơ chế sinh hóa giữa AHA, BHA và Niacinamide trong điều trị mụn và thu nhỏ lỗ chân lông', 'Nồng độ bao nhiêu là an toàn cho da người Việt? Cách kết hợp bộ ba hoạt chất vàng để triệt tiêu sợi bã nhờn mà không phá hủy hàng rào bảo vệ da.', 'ingredients', 'dr_lan_anh', '10/09/2026', '09:45', '9 phút đọc', 5320, 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=1400&q=85&auto=format&fit=crop', 'Viện Kiểm nghiệm Dược phẩm & Hóa mỹ phẩm Trung ương', 'Bản phân tích chuyên sâu phân tử lượng, tính tan trong nước và lipid của Glycolic Acid, Salicylic Acid và dẫn xuất Nicotinamide trong phác đồ da liễu.', '{"quote": "Làn da của người Á Đông có lớp trung bì nhiều sắc tố và phản ứng viêm rất nhạy cảm. Đừng sao chép nồng độ acid treatment của phương Tây nếu bạn không muốn đối mặt với cơn ác mộng tăng sắc tố sau viêm (PIH).", "speaker": "BS. CKII Nguyễn Lan Anh"}', '["AHA", "BHA", "Niacinamide", "Trị mụn", "Lỗ chân lông", "Dược mỹ phẩm"]', 'Trong hơn một thập kỷ qua, sự bùng nổ của trào lưu Acid Treatment và các hoạt chất nồng độ cao đã tạo nên một cuộc cách mạng trong nhận thức làm đẹp. Tuy nhiên, sự thiếu hiểu biết về dược lý học và xu hướng lạm dụng nồng độ ''càng cao càng tốt'' đã đẩy hàng nghìn người vào tình trạng teo da, bỏng hóa chất và bùng phát mụn viêm mất kiểm soát. Việc nắm vững cấu trúc hóa học và đích tác động sinh học là chìa khóa then chốt để khai phóng toàn bộ sức mạnh của bộ ba hoạt chất kinh điển này.', 'Một chu trình dưỡng da thành công không phụ thuộc vào giá tiền của sản phẩm, mà nằm ở sự thấu hiểu dược học và khả năng kết hợp nhịp nhàng giữa các hoạt chất. Bằng cách luân phiên sử dụng BHA/AHA để làm sạch sâu và Niacinamide để củng cố tái tạo, bạn sẽ kiến tạo nên một cấu trúc da vững bền và rạng ngời.', '[{"name": "Dung Dịch Tẩy Tế Bào Chết BHA 2% Salicylic Acid Sạch Sâu", "category": "Dược Liệu Tẩy Da Chết", "price": 480000}, {"name": "Tinh Chất Niacinamide 5% Phục Hồi Thu Nhỏ Lỗ Chân Lông", "category": "Serum Cân Bằng", "price": 460000}]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `articles` (`id_article`, `title`, `subtitle`, `id_category`, `id_author`, `published_date`, `time_published`, `read_time`, `views`, `thumbnail`, `photo_credit`, `summary`, `pull_quote`, `tags`, `content_intro`, `content_conclusion`, `recommended_products`) VALUES ('skin-barrier-recovery-14-days', 'Phác đồ cấp cứu da tổn thương và nhiễm corticoid trong 14 ngày: Liệu pháp phục hồi sinh học bằng Centella Asiatica và Panthenol', 'Đối mặt với tình trạng da đỏ rát, lộ mao mạch và ngứa châm chích sau khi dùng kem trộn hoặc peel da hỏng? Bác sĩ da liễu hướng dẫn lộ trình 3 giai đoạn tái thiết cấu trúc biểu mô.', 'treatment', 'dr_lan_anh', '08/09/2026', '16:00', '8 phút đọc', 4540, 'https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?w=1400&q=85&auto=format&fit=crop', 'Khoa Lâm sàng Điều trị Biến chứng Thẩm mỹ Hoàng Bảo', 'Quy trình giải độc da, phác đồ cai nghiện corticoid khoa học, kết hợp hoạt chất Madecassoside phân lập tinh khiết và Vitamin B5 phân tử lượng siêu nhỏ.', '{"quote": "Khi lớp biểu bì bị bào mòn mất khả năng tự vệ, việc nhồi nhét kem dưỡng đậm đặc chỉ làm gia tăng gánh nặng trao đổi chất. Điều làn da cần nhất lúc này là sự tĩnh lặng sinh học và môi trường vô trùng để tái tạo.", "speaker": "BS. CKII Nguyễn Lan Anh"}', '["Corticoid", "Phục hồi màng ẩm", "B5 Panthenol", "Rau má", "Viêm da tiếp xúc"]', 'Tình trạng lạm dụng mỹ phẩm không rõ nguồn gốc chứa dẫn xuất Corticosteroid hoặc lạm dụng phương pháp lột tẩy bằng rượu thuốc, acid nồng độ cao đang là nguyên nhân hàng đầu khiến hàng nghìn phụ nữ rơi vào hội chứng suy giảm hàng rào bảo vệ da trầm trọng. Khi corticoid ức chế hệ miễn dịch cục bộ, mạch máu dưới da bị giãn nở cực độ tạo nên hiện tượng đỏ bừng, teo mô liên kết và mụn mủ bùng phát liên miên.', 'Hàng rào biểu bì của cơ thể sở hữu năng lực tự chữa lành phi thường nếu bạn thấu hiểu cơ chế và trao cho nó thời gian cùng các dưỡng chất tương thích sinh học. Đừng bao giờ đánh đổi sự trắng nhanh tức thời lấy sức khỏe lâu dài của làn da.', '[{"name": "Kem Dưỡng B5 Phục Hồi Chuyên Sâu Hoàng Bảo Cica-Care", "category": "Trị Liệu Phục Hồi", "price": 390000}, {"name": "Xịt Khoáng Tinh Khiết Cấp Cứu Da Tổn Thương Dị Ứng", "category": "Khoáng Y Tế", "price": 260000}]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `articles` (`id_article`, `title`, `subtitle`, `id_category`, `id_author`, `published_date`, `time_published`, `read_time`, `views`, `thumbnail`, `photo_credit`, `summary`, `pull_quote`, `tags`, `content_intro`, `content_conclusion`, `recommended_products`) VALUES ('choose-lipstick-by-undertone', 'Nghệ thuật giải mã Undertone da: Phương pháp xác định sắc độ ngầm và cẩm nang lựa chọn sắc son nâng tầm thần thái', 'Tại sao cùng một thỏi son đỏ lại biến người này thành nữ hoàng bữa tiệc nhưng khiến người khác trông mệt mỏi và vàng răng? Chuyên gia trang điểm hướng dẫn trắc nghiệm sắc độ chuẩn xác.', 'makeup', 'hoang_nam', '05/09/2026', '11:20', '6 phút đọc', 3860, 'https://images.unsplash.com/photo-1586495777744-4413f21062fa?w=1400&q=85&auto=format&fit=crop', 'Hoàng Nam Makeup Academy / Studio Nghệ thuật', 'Phân biệt Skintone và Undertone theo hệ thống bảng màu Munsell, kỹ thuật test tĩnh mạch và cách ứng dụng màu tương phản để tôn vinh nụ cười rạng rỡ.', '{"quote": "Son môi không đơn thuần là một món mỹ phẩm điểm tô màu mè. Đó là chữ ký thị giác đầu tiên thể hiện bản lĩnh, cảm xúc và khí chất riêng biệt của người phụ nữ.", "speaker": "Chuyên gia Hoàng Nam (Giám đốc Nghệ thuật Trang điểm)"}', '["Son môi", "Undertone", "Sắc tố da", "Bí quyết Makeup", "Trang điểm cá nhân"]', 'Trong giới trang điểm chuyên nghiệp quốc tế, có một câu nói kinh điển: ''Không có thỏi son xấu, chỉ có thỏi son đặt sai sắc tố da''. Rất nhiều phụ nữ chi tiêu hàng triệu đồng để sưu tầm các bộ sưu tập son phiên bản giới hạn, nhưng khi thoa lên mặt mộc lại cảm thấy khuôn mặt bị già đi hoặc tái nhợt. Căn nguyên của vấn đề nằm ở sự xung đột giữa quang phổ màu son và sắc tố ngầm dưới da (Undertone).', 'Hiểu rõ sắc tố của bản thân là bước khai mở đầu tiên trên con đường làm chủ nghệ thuật trang điểm. Khi màu son hòa nhịp cùng năng lượng tự nhiên của làn da, nụ cười của bạn sẽ tỏa sáng với trọn vẹn vẻ kiêu sa và cuốn hút.', '[{"name": "Son Kem Lì Nhung Mịn Dưỡng Ẩm Hoàng Bảo Velvet Lip Tint", "category": "Son Môi Cao Cấp", "price": 290000}, {"name": "Chì Định Hình Viền Môi Chống Trôi Sắc Nét", "category": "Trang Điểm Môi", "price": 180000}]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `articles` (`id_article`, `title`, `subtitle`, `id_category`, `id_author`, `published_date`, `time_published`, `read_time`, `views`, `thumbnail`, `photo_credit`, `summary`, `pull_quote`, `tags`, `content_intro`, `content_conclusion`, `recommended_products`) VALUES ('clean-beauty-trend-2026', 'Làn sóng Clean Beauty 2026: Tương lai của mỹ phẩm thuần chay sinh học và trách nhiệm sinh thái toàn cầu', 'Tại sao các tập đoàn mỹ phẩm xa xỉ đang ráo riết tái cấu trúc chuỗi cung ứng theo tiêu chuẩn thuần chay và bao bì phân hủy sinh học? Phóng sự độc quyền về xu hướng tiêu dùng tỉnh thức.', 'trends', 'mai_phuong', '01/09/2026', '15:30', '7 phút đọc', 5120, 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=1400&q=85&auto=format&fit=crop', 'Reuters / Diễn đàn Mỹ phẩm Sinh học Bền vững Quốc tế', 'Khảo sát sự dịch chuyển thói quen tiêu dùng của thế hệ Gen Z và Millennials đối với tiêu chuẩn Cruelty-Free, canh tác nông nghiệp tái sinh và chứng nhận Eco-friendly.', '{"quote": "Làm đẹp đích thực trong kỷ nguyên mới không thể xây dựng trên sự tổn hại của muôn loài hay rác thải nhựa đại dương. Một sản phẩm chân chính phải đẹp từ công thức đến đạo đức sản xuất.", "speaker": "Nhà báo Mai Phương (Ban Xu hướng & Môi trường sống)"}', '["Clean Beauty", "Mỹ phẩm thuần chay", "Bền vững", "Vegan", "Môi trường sống"]', 'Tại Tuần lễ Mỹ phẩm Bền vững Quốc tế diễn ra vào đầu năm 2026, hơn 82% các nhà phân phối và bán lẻ mỹ phẩm cao cấp xác nhận rằng tiêu chí ''Thuần chay'' (Vegan) và ''Bảo vệ động vật'' (Cruelty-Free) đã vươn lên thành yếu tố quyết định hàng đầu trong hành vi mua sắm của thế hệ trẻ. Khái niệm Clean Beauty đã vượt thoát khỏi ranh giới của một xu hướng tiếp thị nhất thời để trở thành một bộ quy chuẩn đạo đức sống còn đối với toàn bộ ngành công nghiệp tỷ đô.', 'Khi chúng ta đưa ra quyết định lựa chọn một chai mỹ phẩm xanh, đó không chỉ là sự chăm chút cho diện mạo cá nhân, mà là một lá phiếu ủng hộ một tương lai nhân đạo, bền vững và tràn đầy lòng trắc ẩn đối với hành tinh này.', '[{"name": "Sữa Rửa Mặt Hữu Cơ Bọt Mịn Chiết Xuất Tràm Trà Sinh Học", "category": "Mỹ Phẩm Xanh", "price": 280000}, {"name": "Nước Hoa Hồng Cân Bằng Cấp Ẩm Chuyên Sâu Hoàng Bảo", "category": "Thuần Chay", "price": 350000}]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);
INSERT INTO `ingredient_guides` (`name`, `scientific_name`, `role`, `suitable_for`, `note`, `dosage`) VALUES ('AHA (Glycolic / Lactic Acid)', 'Alpha Hydroxy Acid', 'Tẩy tế bào chết bề mặt, kích thích tăng sinh chu kỳ biểu bì, làm sáng các vết thâm nắng và đốm nâu li ti.', 'Da sần sùi, da thô ráp, da khô mất nước, da có nếp nhăn li ti', 'Nên dùng buổi tối, bắt buộc bôi kem chống nắng SPF 50+ phổ rộng ban ngày.', 'Nồng độ 5% - 7% cho người mới bắt đầu');
INSERT INTO `ingredient_guides` (`name`, `scientific_name`, `role`, `suitable_for`, `note`, `dosage`) VALUES ('BHA (Salicylic Acid)', 'Beta Hydroxy Acid (2-Hydroxybenzoic acid)', 'Tan trong dầu, thâm nhập sâu vào nang lông, hóa lỏng bã nhờn, tiêu sừng và diệt khuẩn mụn kỵ khí.', 'Da dầu nhờn, da mụn ẩn, mụn đầu đen, bít tắc nang lông, lỗ chân lông to', 'Bắt đầu từ nồng độ 1-2%, dùng 2-3 lần/tuần để tránh hiện tượng khô căng cục bộ.', 'Nồng độ 1% - 2% chuẩn da liễu');
INSERT INTO `ingredient_guides` (`name`, `scientific_name`, `role`, `suitable_for`, `note`, `dosage`) VALUES ('Hyaluronic Acid (HA)', 'Sodium Hyaluronate đa phân tử', 'Ngậm nước gấp 1000 lần trọng lượng phân tử, giữ ẩm đa tầng từ màng đáy đến bề mặt, tạo độ căng bóng sinh học.', 'Mọi loại da, đặc biệt là da dầu thiếu nước, da khô rát, da sau điều trị laser', 'Thoa trên nền da còn ẩm để tránh hiện tượng thẩm thấu ngược (hút ẩm ngược từ da ra không khí).', 'Dùng hàng ngày 2 lần sáng & tối');
INSERT INTO `ingredient_guides` (`name`, `scientific_name`, `role`, `suitable_for`, `note`, `dosage`) VALUES ('Niacinamide (Vitamin B3)', 'Nicotinamide / 3-Pyridinecarboxamide', 'Thu nhỏ lỗ chân lông, điều tiết bã nhờn, kích thích tổng hợp Ceramide tự thân, ức chế vận chuyển sắc tố Melanin.', 'Da dầu mụn, da thâm sau mụn, da xỉn màu, da tổn thương hàng rào lipid', 'Rất lành tính, hoạt động ở pH trung tính 6.0, kết hợp tốt với B5 và Peptides.', 'Nồng độ tối ưu 2% - 5%');
INSERT INTO `ingredient_guides` (`name`, `scientific_name`, `role`, `suitable_for`, `note`, `dosage`) VALUES ('Retinol & Bakuchiol', 'Vitamin A derivative & Phyto-Retinol', 'Tăng sinh Collagen type I và III, làm mờ nếp nhăn sâu, tăng tốc chu kỳ thay mới tế bào, ngăn ngừa lão hóa sớm.', 'Da bắt đầu lão hóa từ tuổi 22+, da có đốm đồi mồi, da dày sừng', 'Cần cấp ẩm kỹ bằng B5/Ceramide, bắt đầu từ nồng độ thấp đến cao, dùng cách ngày.', 'Nồng độ khởi đầu 0.1% - 0.3%');
INSERT INTO `ingredient_guides` (`name`, `scientific_name`, `role`, `suitable_for`, `note`, `dosage`) VALUES ('Centella Asiatica & B5', 'Madecassoside & D-Panthenol', 'Làm dịu phản ứng viêm cấp tính, hạ nhiệt làn da bỏng rát, sửa chữa cấu trúc mô liên kết và phục hồi mao mạch.', 'Da nhạy cảm, da sau peel, da tổn thương do kem trộn hoặc corticoid', 'Có thể thoa dặm nhiều lần trong ngày khi thấy da bị căng rát, không gây bí bách nang lông.', 'Dùng tự do theo nhu cầu phục hồi');
