INSERT INTO `reviews` (`id_product`, `id_user`, `id_order_detail`, `rating_point`, `content`, `created_at`) VALUES (3, 5, 2, 5.0, 'Kem dưỡng phục hồi B5+ chân ái của mình mỗi khi nặn mụn xong. Giảm đỏ rát rất rõ rệt chỉ sau 1 đêm. 10/10!', '2026-09-02 10:15:00');
