INSERT INTO `feedbacks` (`name`, `email`, `phone`, `subject`, `message`, `is_read`, `created_at`) VALUES ('Trần Bảo Ngọc', 'baongoc.tran@gmail.com', '0938123456', 'Tư vấn phác đồ chăm sóc da dầu mụn ẩn', 'Chào Hoàng Bảo Cosmetics, da em thuộc loại da dầu nhiều, vùng chữ T bóng nhờn và đang bị mụn ẩn li ti ở trán và hai bên má. Em muốn nhờ shop tư vấn giúp em một chu trình làm sạch và phục hồi phù hợp với ngân sách sinh viên ạ. Em cảm ơn shop!', b'1', '2026-09-10 09:30:00');
INSERT INTO `feedbacks` (`name`, `email`, `phone`, `subject`, `message`, `is_read`, `created_at`) VALUES ('Nguyễn Đức Thành', 'ducthanh.spa@gmail.com', '0918765432', 'Hỏi về chính sách đại lý & lấy sỉ mỹ phẩm chính hãng', 'Kính gửi Ban Quản Trị, bên mình hiện đang vận hành chuỗi spa tại Đà Nẵng và muốn tìm kiếm nguồn cung ứng ổn định cho các dòng dược mỹ phẩm La Roche-Posay, CeraVe và Bioderma. Rất mong nhận được thông tin chiết khấu và chính sách đại lý qua email.', b'1', '2026-09-12 14:15:00');
INSERT INTO `feedbacks` (`name`, `email`, `phone`, `subject`, `message`, `is_read`, `created_at`) VALUES ('Lê Thúy Nga', 'thuynga.le@gmail.com', '0909112233', 'Thắc mắc về thời gian giao hàng tại Cần Thơ', 'Shop cho mình hỏi nếu mình đặt đơn hàng trị giá hơn 800k giao về quận Ninh Kiều, Cần Thơ thì khoảng bao lâu nhận được hàng ạ? Đơn hàng có được freeship và cho kiểm tra hàng trước khi thanh toán không shop?', b'0', '2026-09-18 16:40:00');
INSERT INTO `feedbacks` (`name`, `email`, `phone`, `subject`, `message`, `is_read`, `created_at`) VALUES ('Võ Thị Thanh Thảo', 'thanhthao.vo@gmail.com', '0945678901', 'Khen ngợi dịch vụ đóng gói và quà tặng kèm', 'Mình vừa nhận được gói hàng trưa nay. Shop đóng gói cực kỳ chỉn chu, có túi bóng khí dày dặn, lại còn tặng kèm mẫu thử tinh chất B5 nữa. Nhân viên tư vấn nhiệt tình, sản phẩm dùng rất thích. Chắc chắn sẽ ủng hộ shop lâu dài!', b'1', '2026-09-19 11:20:00');
INSERT INTO `feedbacks` (`name`, `email`, `phone`, `subject`, `message`, `is_read`, `created_at`) VALUES ('Phạm Hoàng Nam', 'hoangnam.dev@gmail.com', '0988776655', 'Góp ý trải nghiệm thanh toán quét mã MoMo', 'Giao diện website của shop rất đẹp và mượt mà. Tuy nhiên ở bước thanh toán qua cổng MoMo QR, đôi lúc mã QR hiển thị hơi chậm một chút trên Safari di động. Shop kiểm tra tối ưu thêm nhé. Chúc shop ngày càng phát triển!', b'0', '2026-09-20 20:05:00');
